//! Synthetic fixtures for the attestation verifier tests: made-up certificates made with OpenSSL for these tests only.
//! They are NOT a vendor's; nothing here is trusted outside a test. Regenerated 2026-11-13 for ADR 0041's FIDO leaf rules
//! (OU, AAGUID extension, basicConstraints, path length); the hierarchy and its variants are listed beside each constant.

/// A synthetic FIDO root (P-256, CA, no path length).
pub const ROOT_DER: &str = "";
/// Its intermediate (CA, path length 0).
pub const INT_DER: &str = "";
/// A token's certificate: OU `Authenticator Attestation`, CA:FALSE, AAGUID extension 5a x16, under INT.
pub const LEAF_DER: &str = "";
/// A synthetic RSA root.
pub const RROOT_DER: &str = "";
/// INT's key and name, signed by the RSA root.
pub const RINT_DER: &str = "";
/// LEAF with a one-day validity.
pub const LEAF_SHORT_DER: &str = "";
/// LEAF but with another OU.
pub const LEAF_NO_OU_DER: &str = "";
/// LEAF with no basicConstraints at all.
pub const LEAF_NO_BC_DER: &str = "";
/// LEAF with no AAGUID extension.
pub const LEAF_NO_AAGUID_DER: &str = "";
/// LEAF whose AAGUID extension is 6b x16.
pub const LEAF_WRONG_AAGUID_DER: &str = "";
/// LEAF whose AAGUID extension is marked critical.
pub const LEAF_CRIT_AAGUID_DER: &str = "";
/// LEAF that says it may sign certificates.
pub const LEAF_KEY_CERT_SIGN_DER: &str = "";
/// A U2F-style leaf: no OU, no AAGUID, no basicConstraints.
pub const LEAF_U2F_DER: &str = "";
/// A synthetic multi-purpose root (path length 3), the shape of a root that signs FIDO and PIV intermediates.
pub const PROOT_DER: &str = "";
/// Its FIDO attestation intermediate (path length 0).
pub const FINT_DER: &str = "";
/// Its PIV attestation intermediate (path length 1).
pub const PINT_DER: &str = "";
/// A PIV device CA under it.
pub const PDEV_DER: &str = "";
/// A PIV slot certificate under the device CA (the leaf key is the tests' leaf key; no OU, no AAGUID).
pub const PSLOT_DER: &str = "";
/// A device CA under the FIDO intermediate (a CA below a path length 0 intermediate).
pub const FDEV_DER: &str = "";
/// A full FIDO leaf under that device CA.
pub const FLEAF_DER: &str = "";
/// The tests' token key (PKCS#8), the key of every leaf above.
pub const LEAF_KEY_PKCS8: &str = "308187020100301306072a8648ce3d020106082a8648ce3d030107046d306b0201010420617c32cf1d481689d5119a00ed5dad52523eb49ceeae255437b84ae91e1f0dd3a14403420004ede4f664e9edfb608542ec0a3db16e8f6802a31e1f9c4c965bc80847867a3ae4b8c30783873b24f594331f1cbe9b1fa49ba1a6e7924ec360a44f49b66a85cdbf";

/// A synthetic root for the PIV-in-the-u2f-layout test (P-256, CA).
pub const PIVROOT_DER: &str = "";
/// A leaf with the tests' token key that carries an extension of Yubico's PIV attestation arc (1.3.6.1.4.1.41482.3.3), signed
